if(!$out.StartsWith('I:\WGCombat\CP06A-')-or !$build.StartsWith('I:\WGCombat\CP06A-')){throw 'Owned CP05C paths required'}
if(Test-Path $out){throw 'Fresh output required'};if(Get-Process WanxiangGuitu -ErrorAction SilentlyContinue){throw 'Player conflict'}
$exe=Join-Path $build 'WanxiangGuitu.exe';$release=Get-Content "$exe.release.json" -Raw|ConvertFrom-Json;if((Get-FileHash $exe).Hash.ToLowerInvariant()-ne$release.executableSHA256){throw 'Build identity mismatch'}
