New-Item -ItemType Directory $out|Out-Null
if($SeedPackage){$seed=[IO.Path]::GetFullPath($SeedPackage);if(!$seed.StartsWith('I:\WGCombat\CP06A-')){throw 'Genuine isolated checkpoint source required'};$dest="$out/WanxiangGuitu/ForestRuins";New-Item -ItemType Directory $dest -Force|Out-Null;Copy-Item "$seed/*" $dest;$copy=@(Get-ChildItem $dest -File|ForEach-Object {@{file=$_.Name;sha256=(Get-FileHash $_.FullName).Hash}});@{source=$seed;files=$copy;scope='Unmodified copy of genuine product-created synthetic checkpoint; not hand-edited save'}|ConvertTo-Json -Depth 5|Set-Content "$out/seed-copy.json" -Encoding UTF8}
