$paths=[string[]]@(Get-ChildItem "$out/WanxiangGuitu/ForestRuins" -File -ErrorAction SilentlyContinue|ForEach-Object FullName);[Array]::Sort($paths,[StringComparer]::Ordinal);$ledger=@($paths|ForEach-Object {$_.Substring($out.Length+1).Replace('\','/')+'='+(Get-FileHash -LiteralPath $_).Hash.ToLowerInvariant()});[IO.File]::WriteAllText("$out/canary-before.txt",[string]::Join("`n",$ledger),[Text.UTF8Encoding]::new($false))
$entry='H:/unity/WanxiangGuitu/ProjectDocs/WanxiangGuitu/DeliveryUI01/Automation/Invoke-LocalValidation.ps1';$ast=[Management.Automation.Language.Parser]::ParseFile($entry,[ref]$null,[ref]$null);foreach($name in 'StartChild','FinishChild'){$d=$ast.Find({param($n)$n -is [Management.Automation.Language.FunctionDefinitionAst]-and $n.Name -eq $name},$true);Invoke-Expression $d.Extent.Text}
$script:children=[Collections.Generic.List[object]]::new();$script:desktop='WGTest_'+[guid]::NewGuid().ToString('N');$script:workerReady=$true;$script:workerPath='I:/WGP2/1028-080504-eef74f/Runtime/Worker/NativeProbe.dll';$dotnet=(Get-Command dotnet).Source;$MinimumUnityCommitGB=3

$argsList=@('-wanxiang-storage-root',$out,'-windowed','-screen-width','1280','-screen-height','720','-logFile',"$out/Player.log",'-cp05-c');if($Mode-eq'training'){$argsList+='-cp05-training'}else{$argsList+='-cpc-formal'}
$t=StartChild $exe $argsList "$out/Player" $out $true;$deadline=[datetime]::UtcNow.AddSeconds(300);while(!$t.process.HasExited-and[datetime]::UtcNow-lt$deadline){Start-Sleep -Milliseconds 200}
$ended=$t.process.HasExited;FinishChild $t;$code=if($ended){$t.process.ExitCode}else{$null};@{exited=$ended;exitCode=$code;timedOut=!$ended;forcedTermination=$false;layer='isolated nondevelopment controlled API; NOT native/human'}|ConvertTo-Json|Set-Content "$out/runtime.json" -Encoding UTF8
if(!$ended){throw 'Bounded timeout; no force termination'};if(!(Test-Path "$out/probe.json")){throw 'INCOMPLETE: no runtime semantic receipt'};$receipt=Get-Content "$out/probe.json" -Raw|ConvertFrom-Json;if(@($receipt.rows).Count-eq 0){throw 'Empty runtime receipt'}
if($code-ne 0-or @($receipt.rows|Where-Object status -eq FAIL).Count){exit 1};if(Select-String "$out/Player.log" -Pattern 'NullReferenceException|CP05_TRAINING_FAILED' -Quiet){throw 'Runtime exception despite zero exit'};exit 0
